        return None if s.get('nullable') or s.get('type') == 'null' else path + ' is null'
    t = value_type(v)
    if s.get('type') == 'number' and t in ('integer', 'number'):
        return None
    if t != s.get('type'):
        return path + ': expected ' + _js_string(s.get('type')) + ', got ' + t
    enum = s.get('enum')
    if enum and not any(deep_equal(x, v) for x in enum):
        return path + ': ' + _js_json(v) + ' is not one of ' + ', '.join(_js_string(x) for x in enum)
    if s.get('type') == 'object':
        props = s.get('properties') or {}
        for k, f in props.items():
            if k not in v:
                if f.get('required'):
                    return path + '.' + k + ' is missing'
                continue
            p = check_value(v[k], f, path + '.' + k)
            if p:
                return p
    if s.get('type') == 'array':
        for i, x in enumerate(v):
            p = check_value(x, s.get('items'), path + '[' + str(i) + ']')
            if p:
                return p
