def check_shape(v: Any, shape: Any, name: str) -> dict[str, Any]:
    p = check_value(v, shape, name)
    return {'valid': False, 'message': p} if p else {'valid': True, 'message': ''}


def check_range(v: Any, min_: Any, max_: Any, name: str) -> dict[str, Any]:
    n = to_num(v)
    if not _is_num(v):
        return {'valid': False, 'message': name + ' must be a number'}
    if min_ is not None and min_ != '' and n < to_num(min_):
        return {'valid': False, 'message': name + ' must be ≥ ' + _js_string(min_)}
    if max_ is not None and max_ != '' and n > to_num(max_):
        return {'valid': False, 'message': name + ' must be ≤ ' + _js_string(max_)}
    return {'valid': True, 'message': ''}


def check_regex(v: Any, pattern: str, name: str) -> dict[str, Any]:
    try:
        ok = _regex(pattern).search(str_(v)) is not None
    except re.error:
        return {'valid': False, 'message': 'invalid pattern'}
    return {'valid': True, 'message': ''} if ok else {'valid': False, 'message': name + ' has an invalid format'}


def check_password(v: Any, policy: dict[str, Any], name: str) -> dict[str, Any]:
    p = str_(v)
    if _utf16_len(p) < policy['minLength']:
        return {'valid': False, 'message': name + ' must be at least ' + _js_string(policy['minLength']) + ' characters'}
    if policy['requireDigit'] and not re.search(r'[0-9]', p):
        return {'valid': False, 'message': name + ' must contain a digit'}
    if policy['requireUpper'] and not re.search(r'[A-Z]', p):
        return {'valid': False, 'message': name + ' must contain an uppercase letter'}
    return {'valid': True, 'message': ''}


# ---------- conversion ----------

def to_string(v: Any) -> str:
    """Objects become JSON."""
    return _js_json(v) if isinstance(v, (dict, list)) else _js_string('' if v is None else v)


def to_number(v: Any) -> Any:
    """Not a number → 0."""
    n = _js_number(v)
    return 0 if isinstance(n, float) and math.isnan(n) else n


def is_numeric(v: Any) -> bool:
    n = _js_number(v)
    return not (isinstance(n, float) and math.isnan(n))


def to_boolean(v: Any) -> bool:
    return truthy(v)


def type_of(v: Any) -> str:
    """string, integer, number, boolean, object, array or null."""
    return value_type(v)


# ---------- math ----------

def _finite(x: Any) -> bool:
    return not (isinstance(x, float) and (math.isnan(x) or math.isinf(x)))


def _nan(x: Any) -> bool:
    return isinstance(x, float) and math.isnan(x)


def round_(v: Any, decimals: Any) -> Any:
    """Rounds to 0–15 decimals, halves up."""
    x, d = to_num(v), to_num(decimals)
    f = 10.0 ** (min(15, max(0, int(d))) if _finite(d) else 0)
    y = x * f + 0.5
    return math.floor(y) / f if _finite(y) else x


def floor(v: Any) -> Any:
    x = to_num(v)
    return float(math.floor(x)) if _finite(x) else x


def ceil(v: Any) -> Any:
    x = to_num(v)
    return float(math.ceil(x)) if _finite(x) else x


def abs_(v: Any) -> Any:
    return abs(to_num(v))


def min_(a: Any, b: Any) -> Any:
    x, y = to_num(a), to_num(b)
    return math.nan if _nan(x) or _nan(y) else y if y < x else x


def max_(a: Any, b: Any) -> Any:
    x, y = to_num(a), to_num(b)
    return math.nan if _nan(x) or _nan(y) else y if y > x else x


def clamp(v: Any, lo: Any, hi: Any) -> Any:
    """The value kept between lo and hi."""
    return min_(max_(v, lo), hi)


def power(a: Any, b: Any) -> Any:
    """JavaScript's ** (NaN, infinities and zero as JavaScript has them)."""
    x, y = float(to_num(a)), float(to_num(b))
    if math.isnan(y) or (abs(x) == 1 and math.isinf(y)):
        return math.nan
    odd = y.is_integer() and y % 2 == 1
    try:
        return math.pow(x, y)
    except ValueError:
        return (-math.inf if odd and math.copysign(1, x) < 0 else math.inf) if x == 0 else math.nan
    except OverflowError:
        return -math.inf if odd and x < 0 else math.inf


def sqrt(v: Any) -> Any:
    x = to_num(v)
    return math.nan if _nan(x) or x < 0 else math.sqrt(x)


# ---------- text and encoding (positions count UTF-16 units, like JavaScript) ----------

def _rel_index(v: Any, n: int) -> int:
    """A slice position: negative counts from the end, clamped to 0…n."""
    r = to_num(v)
    if _nan(r):
        return 0
    if isinstance(r, float) and math.isinf(r):
        return n if r > 0 else 0
    i = int(r)
    return max(n + i, 0) if i < 0 else min(i, n)


def _u16(s: str) -> bytes:
    return s.encode('utf-16-le', 'surrogatepass')


def substring(text: Any, start: Any, end: Any) -> str:
    """Like String.prototype.slice; a None end means the end of the text."""
    b = _u16(str_(text))
    n = len(b) // 2
    i = _rel_index(start, n)
    j = n if end is None else _rel_index(end, n)
    return b[2 * i:2 * j].decode('utf-16-le', 'surrogatepass') if j > i else ''


def index_of(text: Any, search: Any) -> int:
    t = str_(text)
    i = t.find(str_(search))
    return -1 if i < 0 else _utf16_len(t[:i])


def _pad(text: Any, length: Any, fill: Any, at_start: bool) -> str:
    t, n = str_(text), to_num(length)
    if _nan(n):
        n = 0
    if n > 100000:
        raise FddError('INVALID_LENGTH', 'Length must be at most 100000')
    f = ' ' if fill is None else str_(fill)
    cur = _utf16_len(t)
    if n <= cur or f == '' or int(n) <= cur:
        return t
    need = int(n) - cur
    fb = _u16(f)
    padding = (fb * (need // (len(fb) // 2) + 1))[:2 * need].decode('utf-16-le', 'surrogatepass')
    return padding + t if at_start else t + padding


def pad_start(text: Any, length: Any, fill: Any) -> str:
    return _pad(text, length, fill, True)


def pad_end(text: Any, length: Any, fill: Any) -> str:
    return _pad(text, length, fill, False)


def _utf8(s: str) -> bytes:
    """UTF-8 bytes; a lone surrogate becomes U+FFFD (TextEncoder)."""
    return _u16(s).decode('utf-16-le', 'replace').encode('utf-8')


def base64_encode(text: Any) -> str:
    """UTF-8 text as Base64."""
    return base64.b64encode(_utf8(str_(text))).decode('ascii')


def base64_decode(text: Any) -> str:
    """Base64 to UTF-8 text; fails with INVALID_BASE64."""
    t = re.sub(r'[\t\n\f\r ]+', '', str_(text))
    if len(t) % 4 == 0:
        t = re.sub(r'={1,2}\Z', '', t)
    if len(t) % 4 == 1 or not re.fullmatch(r'[A-Za-z0-9+/]*', t):
        raise FddError('INVALID_BASE64', 'Not valid Base64')
    return base64.b64decode(t + '=' * ((4 - len(t) % 4) % 4)).decode('utf-8', 'replace')


def format_number(value: Any, decimals: Any, thousands: Any, point: Any) -> str:
    """Fixed decimals (halves up) and a thousands separator; fails with INVALID_NUMBER."""
    d0 = to_num(decimals)
    d = min(15, max(0, int(d0))) if _finite(d0) else 0
    r = round_(value, d)
    if not _finite(r) or abs(r) >= 1e21:
        raise FddError('INVALID_NUMBER', 'Not a number that can be formatted')
    whole, _, frac = f'{abs(r):.{d}f}'.partition('.')
    sign = '-' if r < 0 and any(c in '123456789' for c in whole + frac) else ''
    groups: list[str] = []
    while len(whole) > 3:
        groups.insert(0, whole[-3:])
        whole = whole[:-3]
    return sign + str_(thousands).join([whole, *groups]) + (str_(point) + frac if frac else '')


def _hash_algorithm(a: Any) -> str:
    """sha256, sha1 or md5 ("SHA-256" too); fails with INVALID_ALGORITHM."""
    k = str_(a).strip().lower().replace('-', '')
    if k not in ('sha256', 'sha1', 'md5'):
        raise FddError('INVALID_ALGORITHM', 'Unknown hash algorithm "' + str_(a) + '" (use sha256, sha1 or md5)')
    return k


def _encode_digest(b: bytes, encoding: Any) -> str:
    """hex or base64; fails with INVALID_ENCODING."""
    e = str_(encoding).strip().lower()
    if e == 'hex':
        return b.hex()
    if e == 'base64':
        return base64.b64encode(b).decode('ascii')
    raise FddError('INVALID_ENCODING', 'Unknown encoding "' + str_(encoding) + '" (use hex or base64)')


def hash_(text: Any, algorithm: Any, encoding: Any) -> str:
    """SHA-256, SHA-1 or MD5 of UTF-8 text, as hex or Base64."""
    alg = _hash_algorithm(algorithm)
    return _encode_digest(hashlib.new(alg, _utf8(str_(text))).digest(), encoding)


def hmac_(text: Any, key: Any, algorithm: Any, encoding: Any) -> str:
    """HMAC of UTF-8 text with a UTF-8 key, as hex or Base64."""
    alg = _hash_algorithm(algorithm)
    return _encode_digest(_hmac.new(_utf8(str_(key)), _utf8(str_(text)), alg).digest(), encoding)


def url_encode(text: Any) -> str:
    """encodeURIComponent."""
    return urllib.parse.quote(_utf8(str_(text)), safe="!~*'()")


def url_decode(text: Any) -> str:
    """decodeURIComponent; fails with INVALID_URL_ENCODING."""
    s, out, buf, i = str_(text), [], bytearray(), 0
    try:
        while i < len(s):
            if s[i] == '%':
                h = s[i + 1:i + 3]
                if not re.fullmatch(r'[0-9A-Fa-f]{2}', h):
                    raise ValueError(h)
                buf.append(int(h, 16))
                i += 3
                continue
            if buf:
                out.append(buf.decode('utf-8'))
                buf = bytearray()
            out.append(s[i])
            i += 1
        if buf:
            out.append(buf.decode('utf-8'))
    except ValueError:
        raise FddError('INVALID_URL_ENCODING', 'Not valid URL encoding') from None
    return ''.join(out)


# ---------- records and lists ----------

_INDEX_KEY = re.compile(r'0|[1-9][0-9]*')


def _is_index_key(k: str) -> bool:
    return _INDEX_KEY.fullmatch(k) is not None and int(k) < 4294967295


def keys(o: Any) -> list[str]:
    """Field names in JavaScript's order: integer-like keys ascending, then the rest as inserted."""
    if not isinstance(o, dict):
        return []
    return sorted((k for k in o if _is_index_key(k)), key=int) + [k for k in o if not _is_index_key(k)]


def values(o: Any) -> list[Any]:
    return [o[k] for k in keys(o)]


def entries(o: Any) -> list[dict[str, Any]]:
    return [{'key': k, 'value': o[k]} for k in keys(o)]


def slice_(a: Any, start: Any, end: Any) -> list[Any]:
    """Like Array.prototype.slice; a None end means the end of the list."""
    lst = as_array(a)
    i = _rel_index(start, len(lst))
    j = len(lst) if end is None else _rel_index(end, len(lst))
    return lst[i:j]


def reverse(a: Any) -> list[Any]:
    return list(reversed(as_array(a)))


def unique(a: Any) -> list[Any]:
    """Deep-equal duplicates removed, first kept."""
    out: list[Any] = []
    for x in as_array(a):
        if not any(deep_equal(x, y) for y in out):
            out.append(x)
    return out


def item_index(a: Any, value: Any) -> int:
    """Deep-equal position, or -1."""
    return next((i for i, x in enumerate(as_array(a)) if deep_equal(x, value)), -1)


def flatten(a: Any) -> list[Any]:
    """One level."""
    out: list[Any] = []
    for x in as_array(a):
        if isinstance(x, list):
            out.extend(x)
        else:
            out.append(x)
    return out


# ---------- dates: ISO 8601 text in UTC; numbers are epoch milliseconds ----------

_DATE_RE = re.compile(r'([0-9]{4})-([0-9]{2})-([0-9]{2})(?:[Tt ]([0-9]{2}):([0-9]{2})(?::([0-9]{2})(?:\.([0-9]+))?)?)?(?:([Zz])|([+-])([0-9]{2}):?([0-9]{2}))?')
_MIN_MS, _MAX_MS = -62167219200000, 253402300799999
_UNITS = {
    'millisecond': 1, 'milliseconds': 1, 'ms': 1, 'second': 1000, 'seconds': 1000, 'minute': 60000, 'minutes': 60000, 'hour': 3600000, 'hours': 3600000,
    'day': 86400000, 'days': 86400000, 'week': 604800000, 'weeks': 604800000, 'month': -1, 'months': -1, 'year': -12, 'years': -12,
}
_MONTHS = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December']
_WEEKDAYS = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday']
_TOKENS = ['yyyy', 'yy', 'MMMM', 'MMM', 'MM', 'M', 'dd', 'd', 'EEEE', 'EEE', 'HH', 'H', 'hh', 'h', 'mm', 'm', 'ss', 's', 'SSS', 'a']


def _days_from_civil(y: int, m: int, d: int) -> int:
    """Days since 1970-01-01 (proleptic Gregorian)."""
    y -= 1 if m <= 2 else 0
    era = y // 400
    yoe = y - era * 400
    doy = (153 * (m + (-3 if m > 2 else 9)) + 2) // 5 + d - 1
    return era * 146097 + yoe * 365 + yoe // 4 - yoe // 100 + doy - 719468


def _civil_from_days(z: int) -> tuple[int, int, int]:
    z += 719468
    era = z // 146097
    doe = z - era * 146097
    yoe = (doe - doe // 1460 + doe // 36524 - doe // 146096) // 365
    doy = doe - (365 * yoe + yoe // 4 - yoe // 100)
    mp = (5 * doy + 2) // 153
    m = mp + (3 if mp < 10 else -9)
    return yoe + era * 400 + (1 if m <= 2 else 0), m, doy - (153 * mp + 2) // 5 + 1


def _days_in(y: int, m: int) -> int:
    if m == 2:
        return 29 if y % 4 == 0 and (y % 100 != 0 or y % 400 == 0) else 28
    return 30 if m in (4, 6, 9, 11) else 31


def _date_ms(v: Any) -> int | None:
    """Epoch milliseconds of a date (years 0–9999), or None."""
    if _is_num(v):
        if not _finite(v):
            return None
        ms = int(v)
    elif isinstance(v, str):
        m = _DATE_RE.fullmatch(v.strip())
        if not m:
            return None
        y, mo, d, h, mi, s = (int(m.group(k) or 0) for k in range(1, 7))
        if not (1 <= mo <= 12 and 1 <= d <= _days_in(y, mo) and h <= 23 and mi <= 59 and s <= 59):
            return None
        if m.group(9) and (int(m.group(10)) > 23 or int(m.group(11)) > 59):
            return None
        off = int(m.group(10)) * 60 + int(m.group(11)) if m.group(9) else 0
        frac = int(((m.group(7) or '') + '000')[:3])
        ms = (_days_from_civil(y, mo, d) * 86400 + h * 3600 + mi * 60 + s) * 1000 + frac - (-off if m.group(9) == '-' else off) * 60000
    else:
        return None
    return ms if _MIN_MS <= ms <= _MAX_MS else None


def _need_date(v: Any) -> int:
    ms = _date_ms(v)
    if ms is None:
        raise FddError('INVALID_DATE', 'Not a valid date')
    return ms


def _date_fields(ms: int) -> list[int]:
    """[year, month, day, hour, minute, second, millisecond, weekday (0 = Sunday), time of day]."""
    days = ms // 86400000
    t = ms - days * 86400000
    y, m, d = _civil_from_days(days)
    return [y, m, d, t // 3600000, t // 60000 % 60, t // 1000 % 60, t % 1000, (days % 7 + 11) % 7, t]


def _iso_date(ms: Any) -> str:
    if not (_MIN_MS <= ms <= _MAX_MS):
        raise FddError('INVALID_DATE', 'The date is out of range')
    p = _date_fields(int(ms))
    return f'{p[0]:04d}-{p[1]:02d}-{p[2]:02d}T{p[3]:02d}:{p[4]:02d}:{p[5]:02d}.{p[6]:03d}Z'


def _time_unit(u: Any) -> int:
    """Milliseconds of a unit; months are -1 and years -12."""
    k = str_(u).strip().lower()
    if k not in _UNITS:
        raise FddError('INVALID_UNIT', 'Unknown time unit "' + str_(u) + '"')
    return _UNITS[k]


def parse_date(v: Any) -> dict[str, Any]:
    """A date as UTC date-time text and epoch milliseconds."""
    ms = _date_ms(v)
    return {'date': None, 'timestamp': None, 'valid': False} if ms is None else {'date': _iso_date(ms), 'timestamp': ms, 'valid': True}


def format_date(date: Any, pattern: Any) -> str:
