        'EEEE': day, 'EEE': day[:3], 'HH': f'{p[3]:02d}', 'H': str(p[3]), 'hh': f'{h12:02d}', 'h': str(h12), 'mm': f'{p[4]:02d}', 'm': str(p[4]),
