            continue
        tok = next((t for t in _TOKENS if f.startswith(t, i)), None)
        out.append(val[tok] if tok else f[i])
        i += len(tok) if tok else 1
    return ''.join(out)


def add_time(date: Any, amount: Any, unit: Any) -> str:
    """Months and years keep the day, clamped to the end of the month."""
    ms, u, n = _need_date(date), _time_unit(unit), to_num(amount)
