def date_parts(date: Any) -> dict[str, int]:
    """year … millisecond in UTC, weekday 1 = Monday … 7 = Sunday."""
    p = _date_fields(_need_date(date))
    return {'year': p[0], 'month': p[1], 'day': p[2], 'hour': p[3], 'minute': p[4], 'second': p[5], 'millisecond': p[6], 'weekday': 7 if p[7] == 0 else p[7]}


def make_date(year: Any, month: Any, day: Any, hour: Any, minute: Any, second: Any) -> str:
    """A UTC date-time from its parts; fails with INVALID_DATE."""
    vals = [to_num(x) for x in (year, month, day, hour, minute, second)]
    if not all(_is_num(x) and _finite(x) and float(x).is_integer() for x in vals):
        raise FddError('INVALID_DATE', 'Not a valid date')
