_PERIODS = ['hour', 'hours', 'day', 'days', 'week', 'weeks', 'month', 'months', 'year', 'years']


def _period_edge(date: Any, unit: Any, end: bool) -> str:
    """First (or last) millisecond of the hour, day, week from Monday, month or year; fails with INVALID_UNIT."""
    ms = _need_date(date)
    p = _date_fields(ms)
    day = ms // 86400000 * 86400000
    k = str_(unit).strip().lower()
    if k not in _PERIODS:
        raise FddError('INVALID_UNIT', 'Unknown period "' + str_(unit) + '" (use hour, day, week, month or year)')
    u = _PERIODS.index(k) // 2
    if u == 0:
        start, length = ms - p[8] % 3600000, 3600000
