        start, length = day, 86400000
    elif u == 2:
        start, length = day - (p[7] + 6) % 7 * 86400000, 604800000
    elif u == 3:
        start, length = _days_from_civil(p[0], p[1], 1) * 86400000, _days_in(p[0], p[1]) * 86400000
    else:
        start = _days_from_civil(p[0], 1, 1) * 86400000
        length = _days_from_civil(p[0] + 1, 1, 1) * 86400000 - start
    return _iso_date(start + length - 1 if end else start)


def start_of(date: Any, unit: Any) -> str:
    """The first moment of the period the date is in (UTC)."""
    return _period_edge(date, unit, False)


def end_of(date: Any, unit: Any) -> str:
    """The last moment (…:59.999) of the period the date is in (UTC)."""
    return _period_edge(date, unit, True)


# ---------- runtime ----------

def now() -> str:
    """Current date-time (ISO, like JavaScript's toISOString)."""
    return _datetime.datetime.now(_datetime.UTC).isoformat(timespec='milliseconds').replace('+00:00', 'Z')


def uuid() -> str:
    return str(_uuid.uuid4())


def random(min_: Any, max_: Any) -> int:
    """Integer between min and max."""
    lo, hi = to_num(min_), to_num(max_)
    return math.floor(lo + _random.random() * (hi - lo + 1))


def log(message: Any) -> None:
    print(message if isinstance(message, str) else _js_json(message))


async def sleep(ms: Any) -> None:
    await asyncio.sleep(to_num(ms) / 1000)


async def parallel(*branches: Callable[[], Awaitable[None]]) -> None:
    """Runs branches concurrently and waits for all."""
    await asyncio.gather(*(b() for b in branches))
